package com.lamggm.rospocket;
import android.graphics.*;import android.view.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class FreeGridPreviewTest {
 @Test @Config(qualifiers="w1200dp-h900dp") public void tabletReadAndEditDark()throws Exception{render("tablet-dark",1200,900,"dark");}
 @Test @Config(qualifiers="w400dp-h1000dp") public void phoneReadAndEditLight()throws Exception{render("phone-light",400,1000,"light");}
 void render(String name,int width,int height,String theme)throws Exception{ConnectionActivityTest f=new ConnectionActivityTest();f.setup();try{UiTheme.save(f.a,theme);f.a.applyAppearance();f.call("showSection",new Class<?>[]{int.class},2);f.paint();View root=f.a.getWindow().getDecorView().findViewWithTag("app-root");DashboardBoard b=root.findViewWithTag("dashboard-board");for(boolean edit:new boolean[]{false,true}){if(edit)b.edit();root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));root.layout(0,0,width,height);View pencil=b.findViewWithTag("dashboard-edit");if(!edit){assertEquals(View.VISIBLE,pencil.getVisibility());assertEquals(Math.round(48*f.a.getResources().getDisplayMetrics().density),pencil.getWidth());}else assertEquals(View.GONE,pencil.getVisibility());Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);root.draw(new Canvas(bitmap));String folder=System.getenv("POCKET_FREE_GRID_PREVIEW_DIR");if(folder!=null){java.nio.file.Files.createDirectories(java.nio.file.Paths.get(folder));try(java.io.OutputStream out=java.nio.file.Files.newOutputStream(java.nio.file.Paths.get(folder,name+(edit?"-editing":"-reading")+"-HOST-SYNTHETIC.png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}}bitmap.recycle();}}finally{f.cleanup();}}
}
